"""Synthetic independent offset contract; do not reprocess target photographs."""
from pathlib import Path
import os,sys,json,hashlib,subprocess,math
import numpy as np
W=Path(os.environ['W']);O=W/'out';T=W/'temporary';T.mkdir();D=Path('research/hdr-native')
def sha(p):
    with Path(p).open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def save(p,v):p.write_text(json.dumps(v,indent=2,allow_nan=False)+'\n')
assert sys.platform=='darwin' and subprocess.check_output(['sw_vers','-buildVersion'],text=True).strip()=='26A434'
cases=[]
for name,S,H,B,A in [('positive-alt0',.125,1e-7,1/32,0.),('positive-small-alt',.125,1e-7,1/32,2**-16),('negative-source',-2**-9,.01,1/32,2**-16),('negative-target',.125,-1e-5,1/32,2**-15)]:
    S=float(np.float32(S));H=float(np.float32(H));assert S+B>0 and H+A>0;lg=float(np.float32(np.log2((H+A)/(S+B))));code=float(np.float32((lg+32)/40));assert 0<code<1
    cases.append({'id':name,'source':S,'target':H,'base_offset':B,'alternate_offset':A,'gain_min':-32.,'gain_max':8.,'stored_logmap':lg,'gain_code':code})
freeze={'os_build':'26A434','image_version':os.environ.get('ImageVersion'),'synthetic_only':True,'photos_used':False,'cases':cases,'headrooms':[1,1.25,2,4,8],'original_gates':{'linear_max_abs':1e-5,'relative_max':1e-3,'relative_floor':1e-6,'PSNR_peak1_min_db':60,'SDR_max_abs':0},'primary_reference':'https://developer.android.com/media/platform/hdr-image-format#use_the_gain_map_to_create_the_adapted_hdr_rendition','primary_reference_scope':'Independent nonnegative SDR/HDR offsets appear in Ultra HDR reference math. This is not an Apple API conformance claim; original CI is tested separately.','math_prediction':'With fixed offsets, h1=S+B-A. B=A is necessary for exact real-arithmetic h1 identity; finite arithmetic can still differ. Native Apple may choose other host handling, which is what this probe measures.','comparison_candidates':['fixed_offsets','blend_output_offset','scale_both_offsets'],'source_sha256':{p.name:sha(p) for p in [D/'run_hdr_s52.py',D/'offset_collision_s50.m',D/'hdr_headroom_s29.m']},'no_real_photos_or_old_inverse_fit':True,'full_domain_consumer_proof':False}
save(O/'formula-freeze.json',freeze);frozen_sha=sha(O/'formula-freeze.json')
def xml(c):
    seq=''.join('<rdf:li rdf:parseType="Resource">'+''.join(f'<HDRToneMap:{k}>{v:.17g}</HDRToneMap:{k}>' for k,v in [('GainMapMin',-32),('GainMapMax',8),('Gamma',1),('BaseOffset',c['base_offset']),('AlternateOffset',c['alternate_offset'])])+'</rdf:li>' for _ in range(3))
    return '<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#"><rdf:Description xmlns:HDRToneMap="http://ns.apple.com/HDRToneMap/1.0/"><HDRToneMap:Version>1</HDRToneMap:Version><HDRToneMap:BaseHeadroom>0</HDRToneMap:BaseHeadroom><HDRToneMap:AlternateHeadroom>3</HDRToneMap:AlternateHeadroom><HDRToneMap:ChannelMetadata><rdf:Seq>'+seq+'</rdf:Seq></HDRToneMap:ChannelMetadata><HDRToneMap:BaseColorIsWorkingColor>True</HDRToneMap:BaseColorIsWorkingColor></rdf:Description></rdf:RDF></x:xmpmeta>'
flags=['clang','-O2','-fobjc-arc','-framework','Foundation','-framework','CoreImage','-framework','ImageIO','-framework','Metal','-framework','CoreGraphics']
with (O/'build.log').open('w') as log:subprocess.run(flags+[str(D/'offset_collision_s50.m'),'-o',str(W/'native')],stdout=log,stderr=subprocess.STDOUT,check=True,timeout=300)
results=[]
for c in cases:
    folder=T/c['id'];folder.mkdir();mp=folder/'metadata.xml';mp.write_text(xml(c));save(O/(c['id']+'-metadata.json'),{'metadata_sha256':sha(mp),'base_offset':c['base_offset'],'alternate_offset':c['alternate_offset']})
    nativecase={k:c[k] for k in ['id','source','gain_code']};nativecase.update({'metadata_file':str(mp),'temporary_output':str(folder)});save(folder/'inputs.json',{'cases':[nativecase]})
    with (O/(c['id']+'-native.log')).open('w') as log:rc=subprocess.run([str(W/'native'),str(folder/'inputs.json'),str(O/(c['id']+'-native.json'))],stdout=log,stderr=subprocess.STDOUT,timeout=180).returncode
    row={'id':c['id'],'native_returncode':rc,'input':c,'headrooms':[]};results.append(row)
    if rc:row['native_exception']=json.loads((O/(c['id']+'-native.json')).read_text()).get('exception');continue
    native=json.loads((O/(c['id']+'-native.json')).read_text());assert native['AppleFamily4'];nr=native['rows'][0];row['native_input_SHA']={k:nr[k] for k in ['source_texture_sha256','gain_texture_sha256','metadata_sha256']}
    for sample in nr['headrooms']:
        raw=folder/sample['file'];assert sha(raw)==sample['output_sha256'];rgb=np.fromfile(raw,dtype='<f4').reshape(8,8,4)[...,:3].astype('f8');finite=bool(np.isfinite(rgb).all());weight=math.log2(sample['headroom'])/3;gain=2**(weight*(-32+40*c['gain_code']));S=c['source'];B=c['base_offset'];A=c['alternate_offset'];pred={'fixed_offsets':(S+B)*gain-A,'blend_output_offset':(S+B)*gain-((1-weight)*B+weight*A),'scale_both_offsets':(S+weight*B)*gain-weight*A};errors={k:float(abs(rgb-v).max()) if finite else None for k,v in pred.items()};err=float(abs(rgb-c['target']).max()) if finite else None;relative=err/max(abs(c['target']),1e-6) if finite else None;mse=float(np.square(rgb-c['target']).mean()) if finite else None;psnr=(-10*math.log10(mse) if mse else 'inf') if finite else None
        row['headrooms'].append({'headroom':sample['headroom'],'output_SHA256':sample['output_sha256'],'first_RGB':[float(x) if np.isfinite(x) else None for x in rgb[0,0]],'nonfinite_components':int((~np.isfinite(rgb)).sum()),'candidate_max_abs':errors,'h1_source_max_abs':float(abs(rgb-S).max()) if finite and sample['headroom']==1 else None,'h8_target_max_abs':err if sample['headroom']==8 else None,'h8_target_max_relative':relative if sample['headroom']==8 else None,'h8_target_PSNR_peak1_db':psnr if sample['headroom']==8 else None,'h8_target_original_gate':finite and err<=1e-5 and relative<=1e-3 and (psnr=='inf' or psnr>=60) if sample['headroom']==8 else None})
    row['candidate_max_abs_all_headrooms']={key:max((h['candidate_max_abs'][key] for h in row['headrooms'] if h['candidate_max_abs'][key] is not None),default=None) for key in pred};row['unencoded_h1_max0']=row['headrooms'][0]['h1_source_max_abs']==0;row['full_HDR_target_gate']=row['headrooms'][-1]['h8_target_original_gate']
assert sha(O/'formula-freeze.json')==frozen_sha
report={'os_build':'26A434','image_version':os.environ.get('ImageVersion'),'formula_freeze_sha256':frozen_sha,'synthetic_only':True,'photos_used':False,'rows':results,'native_cases_completed':sum(r['native_returncode']==0 for r in results),'requests':4,'h1_identity_cases':sum(r.get('unencoded_h1_max0',False) for r in results),'all_native_cases_h1_max0':all(r.get('unencoded_h1_max0',False) for r in results),'all_native_cases_full_HDR_gate':all(r.get('full_HDR_target_gate',False) for r in results),'no_original_target_or_mask_changed':True,'new_encoded_SDR_ImageIO_verified':False,'scope':'Finite CI API offset contract only; no HEIF, no original-photo numeric fitting, no scene or 33-point proof','acceptance_complete':False,'A_phase_complete':False}
save(O/'analysis-s52.json',report);print(json.dumps({'native_cases_completed':report['native_cases_completed'],'h1_identity_cases':report['h1_identity_cases'],'full_HDR_target_gates':[r.get('full_HDR_target_gate',False) for r in results],'acceptance_complete':False}))
